import { createHmac, timingSafeEqual, randomBytes, pbkdf2Sync } from 'node:crypto';
import { cookies } from 'next/headers';

/**
 * Admin authentication.
 *
 * Two credential formats are supported, so the owner can use whichever is
 * easier to paste into their host's dashboard:
 *
 *   1. `ADMIN_PASSWORD_HASH` = `tf1-<iterations>-<salt-hex>-<hash-hex>`
 *      Recommended. Generated by `npm run make-admin-password`. The whole value
 *      is inside the character set that `.env` and dashboard fields handle
 *      safely — see the note about `$` below.
 *
 *   2. `ADMIN_PASSWORD_HASH` = a bcrypt hash (`$2b$12$…`).
 *      Still accepted for compatibility. Because bcrypt hashes are full of `$`
 *      characters, a value that has been through a dotenv loader is normalised
 *      (escaped dollars, stray quoting, truncated length) before comparison.
 *
 * A single ADMIN_PASSWORD plaintext value is deliberately *not* supported:
 * hashes only, so a leaked environment listing does not reveal the password.
 */

const COOKIE = 'timfire_admin';
const TTL = 30 * 60 * 1000; // 30 minutes
const LOCK = 15 * 60 * 1000; // 15 minutes after five failures
const MAX_ATTEMPTS = 5;

type Attempt = { count: number; until: number };
const attempts: Map<string, Attempt> =
  (globalThis as typeof globalThis & { __tfAttempts?: Map<string, Attempt> }).__tfAttempts ?? new Map();
(globalThis as typeof globalThis & { __tfAttempts?: Map<string, Attempt> }).__tfAttempts = attempts;

/* ── Hash normalisation ──────────────────────────────────────────────────── */

function normaliseBcrypt(raw: string): string {
  let hash = raw.trim();
  if ((hash.startsWith("'") && hash.endsWith("'")) || (hash.startsWith('"') && hash.endsWith('"'))) {
    hash = hash.slice(1, -1).trim();
  }
  // Some loaders double the dollars; others leave them. Collapse repeats.
  hash = hash.replace(/\${2,}/g, '$');
  if (hash.length > 60) {
    const start = hash.indexOf('$2');
    if (start >= 0) hash = hash.slice(start, start + 60);
  }
  return hash;
}

/**
 * Hash format:  tf1-<iterations>-<salt-hex>-<hash-hex>
 *
 * Hyphen separators, not `$`. Next.js (like dotenv-expand) treats `$` as a
 * variable reference and truncates the value after the first one, which makes a
 * bcrypt hash impossible to store in .env or in most dashboards without silent
 * corruption. A hash that is entirely [a-z0-9-] has no such problem.
 */
function verifyTf1(password: string, stored: string): boolean {
  const parts = stored.split('-');
  if (parts.length !== 4 || parts[0] !== 'tf1') return false;
  const iterations = Number(parts[1]);
  const salt = parts[2];
  const expected = parts[3];
  if (!Number.isFinite(iterations) || iterations < 100_000 || !/^[0-9a-f]+$/i.test(salt) || !/^[0-9a-f]+$/i.test(expected)) {
    return false;
  }
  const actual = pbkdf2Sync(password, salt, iterations, expected.length / 2, 'sha256').toString('hex');
  const a = Buffer.from(actual, 'hex');
  const b = Buffer.from(expected, 'hex');
  return a.length === b.length && timingSafeEqual(a, b);
}

async function verifyBcrypt(password: string, stored: string): Promise<boolean> {
  try {
    const bcrypt = (await import('bcryptjs')).default;
    return await bcrypt.compare(password, normaliseBcrypt(stored));
  } catch {
    return false;
  }
}

/* ── Configuration ───────────────────────────────────────────────────────── */

function credentials(): { email: string; hash: string } | null {
  const email = process.env.ADMIN_EMAIL?.trim();
  const hash = process.env.ADMIN_PASSWORD_HASH?.trim();
  return email && hash ? { email, hash } : null;
}

function sign(payload: string, secret: string): string {
  return createHmac('sha256', secret).update(payload).digest('base64url');
}

/** Shared secret for the session signature. Falls back to the hash. */
function secret(hash: string): string {
  return process.env.ADMIN_SESSION_SECRET?.trim() || hash;
}

/* ── Login / session / logout ────────────────────────────────────────────── */

export async function login(email: string, password: string, key: string) {
  const config = credentials();
  if (!config) {
    return {
      ok: false as const,
      code: 503,
      message: 'Sign-in is not configured on this deployment. Set ADMIN_EMAIL and ADMIN_PASSWORD_HASH.',
    };
  }

  const now = Date.now();
  const previous = attempts.get(key);
  if (previous && previous.until > now) {
    return { ok: false as const, code: 429, message: 'Too many attempts. Try again in a few minutes.' };
  }

  const emailMatches = email.trim().toLowerCase() === config.email.toLowerCase();
  const passwordMatches = config.hash.startsWith('tf1-')
    ? verifyTf1(password, config.hash)
    : await verifyBcrypt(password, config.hash);

  if (!emailMatches || !passwordMatches) {
    const count = (previous && previous.until === 0 ? previous.count : 0) + 1;
    attempts.set(key, { count, until: count >= MAX_ATTEMPTS ? now + LOCK : 0 });
    return {
      ok: false as const,
      code: count >= MAX_ATTEMPTS ? 429 : 401,
      message: count >= MAX_ATTEMPTS ? 'Too many attempts. Try again in a few minutes.' : 'Email or password is incorrect.',
    };
  }

  attempts.delete(key);
  const expires = now + TTL;
  const payload = Buffer.from(JSON.stringify({ exp: expires, nonce: randomBytes(16).toString('hex') })).toString('base64url');
  const token = `${payload}.${sign(payload, secret(config.hash))}`;
  (await cookies()).set(COOKIE, token, {
    httpOnly: true,
    secure: process.env.NODE_ENV === 'production',
    sameSite: 'lax',
    path: '/',
    maxAge: TTL / 1000,
  });
  return { ok: true as const, code: 200, message: 'Signed in.', expires };
}

export async function session() {
  const config = credentials();
  const raw = (await cookies()).get(COOKIE)?.value;
  if (!config || !raw) return null;
  const [payload, signature] = raw.split('.');
  if (!payload || !signature) return null;
  const expected = sign(payload, secret(config.hash));
  const a = Buffer.from(signature);
  const b = Buffer.from(expected);
  if (a.length !== b.length || !timingSafeEqual(a, b)) return null;
  try {
    const value = JSON.parse(Buffer.from(payload, 'base64url').toString()) as { exp?: number };
    return value.exp && value.exp > Date.now() ? { expires: value.exp } : null;
  } catch {
    return null;
  }
}

export async function logout() {
  (await cookies()).delete(COOKIE);
}

/** Returns the configured admin email, for display only. */
export function adminEmail(): string {
  return process.env.ADMIN_EMAIL?.trim() || '';
}
